import{_ as s,c as n,o as i,j as t,Y as o,t as r}from"./chunks/framework.BNTND4LZ.js";const u=JSON.parse('{"title":"docker-container-rm | x-cmd man (docker man1) | Remove one or more containers","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-rm - Remove one or more containers","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-rm | x-cmd man (docker man1) | Remove one or more containers"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-rm - Remove one or more containers"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-rm","category":"docker man1","desc":"Remove one or more containers"},"relativePath":"docker/man1/docker-container-rm.md","filePath":"docker/man1/[man].md"}'),h={name:"docker/man1/docker-container-rm.md"},l={class:"visually-hidden"};function d(e,a,c,p,k,m){return i(),n("div",null,[t("h1",l,r(e.$params.man),1),a[0]||(a[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-rm - Remove one or more containers</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container rm [OPTIONS] CONTAINER [CONTAINER...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p><strong>docker container rm</strong> will remove one or more containers from the host node. The container name or ID can be used. This does not remove images. You cannot remove a running container unless you use the <strong>-f</strong> option. To see all containers on a host use the <strong>docker container ls -a</strong> command.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h2 id="removing-a-container-using-its-id" tabindex="-1">Removing a container using its ID <a class="header-anchor" href="#removing-a-container-using-its-id" aria-label="Permalink to &quot;Removing a container using its ID&quot;">​</a></h2><p>To remove a container using its ID, find either from a <strong>docker ps -a</strong> command, or use the ID returned from the <strong>docker run</strong> command, or retrieve it from a file used to store it using the <strong>docker run --cidfile</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> abebf7571666</span></span></code></pre></div><h2 id="removing-a-container-using-the-container-name" tabindex="-1">Removing a container using the container name <a class="header-anchor" href="#removing-a-container-using-the-container-name" aria-label="Permalink to &quot;Removing a container using the container name&quot;">​</a></h2><p>The name of the container can be found using the <strong>docker ps -a</strong> command. The use that name as follows:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hopeful_morse</span></span></code></pre></div><h2 id="removing-a-container-and-all-associated-volumes" tabindex="-1">Removing a container and all associated volumes <a class="header-anchor" href="#removing-a-container-and-all-associated-volumes" aria-label="Permalink to &quot;Removing a container and all associated volumes&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redis</span></span></code></pre></div><p>This command will remove the container and any volumes associated with it. Note that if a volume was specified with a name, it will not be removed.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> awesome:/foo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> redis</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hello</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span></code></pre></div><p>In this example, the volume for <strong>/foo</strong> will remain in tact, but the volume for <strong>/bar</strong> will be removed. The same behavior holds for volumes inherited with <strong>--volumes-from</strong>.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-f</strong>, <strong>--force</strong>[=false] Force the removal of a running container (uses SIGKILL)</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for rm</p><p><strong>-l</strong>, <strong>--link</strong>[=false] Remove the specified link</p><p><strong>-v</strong>, <strong>--volumes</strong>[=false] Remove anonymous volumes associated with the container</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>`,25))])}const F=s(h,[["render",d]]);export{u as __pageData,F as default};
